    function updatePedestrians(time) {
      for (const p of pedestrians) {
        const active = time >= 11 && time < 16;
        const localTime = active
          ? ((time - p.start) % p.duration + p.duration) % p.duration
          : p.duration;

        const moving = active && localTime < p.duration;
        const position = moving
          ? p.startPosition.clone().lerp(p.endPosition, localTime / p.duration)
          : p.endPosition;

        p.group.position.copy(position);
        p.group.position.y = 0.28 + Math.abs(Math.sin(time * 8)) * 0.025;

        const swing = moving ? Math.sin(time * 10) * 0.48 : 0;

        p.leftLeg.rotation.x = swing;
        p.rightLeg.rotation.x = -swing;
        p.leftArm.rotation.x = -swing * 0.72;
        p.rightArm.rotation.x = swing * 0.72;

        if (p.axis === "x") {
          p.group.rotation.y =
            p.direction > 0 ? Math.PI / 2 : -Math.PI / 2;
        } else {
          p.group.rotation.y =
            p.direction > 0 ? 0 : Math.PI;
        }
      }
    }

