      const bodyMaterial = material(color);
      box(w, h, d, bodyMaterial, 0, h / 2, 0, group);
      box(w + 0.4, 0.35, d + 0.4, mats.roof, 0, h + 0.15, 0, group);

      const windowMaterial = material(0x31546b, {
        roughness: 0.25,
        metalness: 0.25
      });

      const columns = Math.max(2, Math.floor(w / 2.2));
      const rows = Math.max(2, Math.floor(h / 2.1));

      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < columns; col++) {
          const wx =
            -w / 2 + ((col + 1) * w) / (columns + 1);
          const wy = 1.2 + row * 1.8;

          if (wy + 0.35 > h - 0.2) continue;

          box(
            0.9,
            0.75,
            0.07,
            windowMaterial,
            wx,
            wy,
            d / 2 + 0.04,
            group
          );
        }
      }

      scene.add(group);
    }

