    function updateSignals(time) {
      const state =
        time < 10.5
          ? "red"
          : time < 11
            ? "amber"
            : time < 16
              ? "green"
              : "red";

      for (const signal of signals) {
        updateSignal(signal, state);
      }
    }

    function updateTram(time) {
      let z;

      if (time < 4) {
        z = THREE.MathUtils.lerp(24, 8.5, time / 4);
      } else if (time < 7) {
        z = 8.5;
      } else if (time < 9) {
        z = THREE.MathUtils.lerp(8.5, -8.5, (time - 7) / 2);
      } else if (time < 11) {
        z = -8.5;
      } else if (time < 18) {
        z = THREE.MathUtils.lerp(-8.5, -24, (time - 11) / 7);
      } else if (time < 21) {
        z = -24;
      } else {
        z = null;
      }

      tram.visible = z !== null;
      if (tram.visible) {
        tram.position.z = z;
      }
    }

    function updateCars(time) {
      const moving = time >= 18;
      const progress = moving
        ? THREE.MathUtils.clamp((time - 18) / 3, 0, 1)
        : 0;
      const eased = progress * progress * (3 - 2 * progress);

      for (const car of cars) {
        if (car.vertical) {
          car.group.position.z = THREE.MathUtils.lerp(
            car.homeZ,
            car.targetZ,
            eased
          );
        } else {
          car.group.position.x = THREE.MathUtils.lerp(
            car.homeX,
            car.targetX,
            eased
          );
        }
      }
    }

    function updateUI(time) {
      let phase = phases[0];

      for (const item of phases) {
        if (time >= item.start) phase = item;
      }

      phaseTitle.textContent = phase.title;
      phaseDescription.textContent = phase.description;
      phaseDot.style.background = `#${phase.color.toString(16).padStart(6, "0")}`;
      phaseDot.style.boxShadow = `0 0 0 5px rgba(${phase.color}, 0.14)`;
      timelineProgress.style.width = `${(time / cycleDuration) * 100}%`;
    }

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      pauseButton.textContent = paused ? "Resume" : "Pause";
    });

    document.getElementById("resetView").addEventListener("click", resetView);

    // -------------------------------------------------------------------------
    // Main loop
    // -------------------------------------------------------------------------

    function animate(now) {
      requestAnimationFrame(animate);

      const dt = Math.min((now - previousTime) / 1000, 0.05);
      previousTime = now;

      if (!paused) {
        simulationTime = (simulationTime + dt) % cycleDuration;
      }

      updateTram(simulationTime);
      updateCars(simulationTime);
      updatePedestrians(simulationTime);
      updateSignals(simulationTime);
      updateUI(simulationTime);
      updateCamera();

      renderer.render(scene, camera);
    }

    requestAnimationFrame(animate);

    window.addEventListener("resize", () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    });
  </script>
